settings.css:
h1 {
position: relative;
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin: 0 auto 40px;
}

p {
margin-block-end :16px;
margin-block-start :16px;
}

ol, ul {
margin-block-end :32px;
margin-block-start :16px;
}

p:first-child {
    -webkit-margin-before: 0;
    margin-block-start: 0;
}
